// --- aliases.js ---
function normalizeConfig(value = {}) {
  const config = { models: [], exclude: [], prefix: '', suffix: '-fc', with_tools: 'required', ...value };
  for (const key of ['models', 'exclude']) {
    if (!Array.isArray(config[key]) || config[key].some(pattern => typeof pattern !== 'string')) {
      throw new Error(`${key} must be an array of model names or * patterns.`);
    }
  }
  for (const key of ['prefix', 'suffix']) {
    if (typeof config[key] !== 'string') throw new Error(`${key} must be a string.`);
  }
  if (!config.prefix && !config.suffix) throw new Error('prefix and suffix cannot both be empty.');
  if (!['required', 'auto'].includes(config.with_tools)) throw new Error('with_tools must be required or auto.');
  return config;
}

function matches(id, pattern) {
  const escaped = pattern.split('*').map(part => part.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
  return new RegExp('^' + escaped.join('.*') + '$').test(id);
}

function selected(id, config) {
  return config.models.some(pattern => matches(id, pattern))
    && !config.exclude.some(pattern => matches(id, pattern));
}

// This is only a fast candidate check. The live catalog resolves collisions.
function candidateForAlias(id, config) {
  if (typeof id !== 'string' || !id.startsWith(config.prefix) || !id.endsWith(config.suffix)) return null;
  const model = id.slice(config.prefix.length, id.length - config.suffix.length);
  return model && selected(model, config) ? model : null;
}

function buildCatalog(payload, config) {
  const originalIds = new Set(payload.data.map(model => model.id));
  const aliases = new Map();
  const extra = [];
  for (const model of payload.data) {
    if (!selected(model.id, config)) continue;
    const id = config.prefix + model.id + config.suffix;
    if (originalIds.has(id) || aliases.has(id)) continue;
    aliases.set(id, model.id);
    // FC aliases speak Chat Completions; do not copy vendor endpoint hints.
    const alias = { id, object: model.object || 'model' };
    for (const key of ['created', 'owned_by']) {
      if (key in model) alias[key] = model[key];
    }
    extra.push(alias);
  }
  return { body: { ...payload, data: [...payload.data, ...extra] }, aliases };
}

// --- content-json.js ---
const HEADER = ['{', '"content"', ':', '"'];
const SPACE = /^[ \t\r\n]$/;
const ESCAPES = { '"': 34, '\\': 92, '/': 47, b: 8, f: 12, n: 10, r: 13, t: 9 };

function invalid(reason) {
  throw new Error('Invalid final-answer JSON: ' + reason);
}

// Only the fixed key "content" is accepted; its value supports every JSON escape.
// Keep a high surrogate pending until its matching low surrogate arrives.
function createContentParser() {
  return {
    phase: 'header', token: 0, offset: 0,
    escaped: false, hexDigits: 0, hexValue: 0, high: null,
  };
}

function decodeUnit(state, code) {
  const low = code >= 0xdc00 && code <= 0xdfff;
  if (state.high !== null) {
    if (!low) invalid('unpaired high surrogate');
    const text = String.fromCharCode(state.high, code);
    state.high = null;
    return text;
  }
  if (low) invalid('unpaired low surrogate');
  if (code >= 0xd800 && code <= 0xdbff) {
    state.high = code;
    return '';
  }
  return String.fromCharCode(code);
}

function readContent(state, fragment) {
  let text = '';
  for (let i = 0; i < fragment.length; i++) {
    const character = fragment[i];
    if (state.phase === 'header') {
      if (state.offset === 0 && SPACE.test(character)) continue;
      const token = HEADER[state.token];
      if (character !== token[state.offset]) invalid('expected {"content":"..."}');
      state.offset++;
      if (state.offset === token.length) {
        state.offset = 0;
        state.token++;
        if (state.token === HEADER.length) state.phase = 'content';
      }
      continue;
    }
    if (state.phase === 'end' || state.phase === 'done') {
      if (SPACE.test(character)) continue;
      if (state.phase === 'done' || character !== '}') invalid('unexpected data after content');
      state.phase = 'done';
      continue;
    }
    if (state.hexDigits) {
      if (!/^[0-9a-fA-F]$/.test(character)) invalid('invalid Unicode escape');
      state.hexValue = state.hexValue * 16 + parseInt(character, 16);
      state.hexDigits--;
      if (!state.hexDigits) text += decodeUnit(state, state.hexValue);
    } else if (state.escaped) {
      state.escaped = false;
      if (character === 'u') {
        state.hexDigits = 4;
        state.hexValue = 0;
      } else {
        const code = ESCAPES[character];
        if (code === undefined) invalid('invalid escape');
        text += decodeUnit(state, code);
      }
    } else if (character === '\\') {
      state.escaped = true;
    } else if (character === '"') {
      if (state.high !== null) invalid('unpaired high surrogate');
      state.phase = 'end';
    } else {
      const code = character.charCodeAt(0);
      if (code < 32) invalid('unescaped control character');
      text += decodeUnit(state, code);
    }
  }
  return text;
}

function finishContent(state) {
  if (state.phase !== 'done') invalid('incomplete arguments');
}

// --- transform.js ---
const FINAL_NAME = '__tfa_final_answer';
const INSTRUCTION = `Write your complete user-facing final answer by calling ${FINAL_NAME} once.
The content argument is the answer itself: preserve the requested depth, language, Markdown, equations and code.
Use the other available tools normally when needed. Finish their work before giving the final answer.
Do not repeat that answer in ordinary text, and do not wait for a result from this final-answer tool.`;
const FINAL_TOOL = {
  type: 'function',
  function: {
    name: FINAL_NAME,
    description: 'Deliver the complete final answer to the user. This is an output channel, not an external action.',
    parameters: {
      type: 'object',
      properties: { content: { type: 'string', description: 'The complete user-facing answer.' } },
      required: ['content'],
      additionalProperties: false,
    },
  },
};

function prepareBody(body, config = {}) {
  const tools = body.tools || [];
  const bypass = body.tool_choice === 'none' || typeof body.tool_choice === 'object'
    || body.functions !== undefined || body.function_call !== undefined
    || (body.response_format && body.response_format.type !== 'text')
    || (body.modalities || []).some(value => value !== 'text')
    || tools.some(tool => tool.function?.name === FINAL_NAME);
  if (bypass) return { body, active: false };
  return {
    active: true,
    body: {
      ...body,
      messages: [{ role: 'system', content: INSTRUCTION }, ...body.messages],
      tools: [...tools, FINAL_TOOL],
      tool_choice: tools.length ? (body.tool_choice === 'required' ? 'required' : config.with_tools || 'required')
        : { type: 'function', function: { name: FINAL_NAME } },
    },
  };
}

function isTruncated(reason) {
  return reason === 'length' || reason === 'content_filter';
}

function finalReason(reason, hasFinal, realCount) {
  return reason === 'tool_calls' && hasFinal && realCount === 0 ? 'stop' : reason;
}

function restoreResponse(body) {
  for (const choice of body.choices || []) {
    const message = choice.message;
    if (!message?.tool_calls) continue;
    const realCalls = [];
    let content = '', hasFinal = false;
    for (const call of message.tool_calls) {
      if (call.function?.name !== FINAL_NAME) {
        realCalls.push(call);
        continue;
      }
      hasFinal = true;
      const parser = createContentParser();
      content += readContent(parser, call.function.arguments);
      if (!isTruncated(choice.finish_reason)) finishContent(parser);
    }
    if (!hasFinal) continue;
    message.content = (message.content || '') + content;
    if (realCalls.length) message.tool_calls = realCalls;
    else delete message.tool_calls;
    choice.finish_reason = finalReason(choice.finish_reason, hasFinal, realCalls.length);
  }
  return body;
}

function createStreamState() {
  return { choices: {} };
}

function createChoice() {
  return { tools: {}, order: [], realCount: 0, hasFinal: false, nextText: 0, finished: false };
}

function classifyTool(choice, tool, isFinal) {
  tool.kind = isFinal ? 'final' : 'real';
  if (isFinal) {
    tool.parser = createContentParser();
    tool.buffer = '';
    choice.hasFinal = true;
  } else tool.outputIndex = choice.realCount++;
}

function consumePart(tool, part, outgoing) {
  if (tool.kind === 'real') outgoing.push({ ...part, index: tool.outputIndex });
  else tool.buffer += readContent(tool.parser, part.function?.arguments || '');
}

function flushPending(tool, outgoing) {
  for (const part of tool.pending) consumePart(tool, part, outgoing);
  delete tool.pending;
  delete tool.name;
}

function acceptPart(choice, part, outgoing) {
  let tool = choice.tools[part.index];
  if (!tool) {
    tool = choice.tools[part.index] = { name: '', pending: [], kind: null };
    choice.order.push(part.index);
  }
  if (tool.kind) {
    consumePart(tool, part, outgoing);
    return;
  }
  tool.name += part.function?.name || '';
  tool.pending.push(part);
  // Arguments establish the name boundary; an exact prefix may still grow.
  if (part.function?.arguments) classifyTool(choice, tool, tool.name === FINAL_NAME);
  else if ((tool.name && !FINAL_NAME.startsWith(tool.name))
    || (part.type && part.type !== 'function')) {
    classifyTool(choice, tool, false);
  }
  if (tool.kind) flushPending(tool, outgoing);
}

function drainFinals(choice, finishing = false) {
  let text = '';
  while (choice.nextText < choice.order.length) {
    const tool = choice.tools[choice.order[choice.nextText]];
    if (!tool.kind) break;
    if (tool.kind === 'real') {
      choice.nextText++;
      continue;
    }
    text += tool.buffer;
    tool.buffer = '';
    // Only later parallel final calls are buffered; the first streams immediately.
    if (!finishing && tool.parser.phase !== 'done') break;
    choice.nextText++;
  }
  return text;
}

function restoreChunk(chunk, state) {
  for (const choice of chunk.choices || []) {
    const current = state.choices[choice.index] ||= createChoice();
    const delta = choice.delta || {};
    const outgoing = [];
    for (const part of delta.tool_calls || []) acceptPart(current, part, outgoing);
    const finishing = choice.finish_reason != null;
    if (finishing) {
      for (const tool of Object.values(current.tools)) {
        if (!tool.kind) {
          classifyTool(current, tool, tool.name === FINAL_NAME);
          flushPending(tool, outgoing);
        }
        if (tool.kind === 'final' && !isTruncated(choice.finish_reason)) finishContent(tool.parser);
      }
      choice.finish_reason = finalReason(choice.finish_reason, current.hasFinal, current.realCount);
      current.finished = true;
    }
    delete delta.tool_calls;
    if (outgoing.length) delta.tool_calls = outgoing;
    const content = drainFinals(current, finishing);
    if (content) delta.content = (delta.content || '') + content;
    choice.delta = delta;
  }
  return chunk;
}

function finishStream(state) {
  const choices = Object.values(state.choices);
  if (!choices.length || choices.some(choice => !choice.finished)) {
    throw new Error('Upstream ended without finish_reason.');
  }
}

